import { listSkuArchivesByStyleId } from '../../data/pcs-sku-archive-repository.ts'
// @page-pattern: list
import { renderStandardListPage, renderStandardListStats } from '../../components/ui/list-page.ts'
import { renderStandardListTable, type StandardListColumn } from '../../components/ui/list-table.ts'
import { renderTablePagination } from '../../components/ui/pagination.ts'
import { ensureFeedbackState, getFeedbackSnapshot, getFeedbackStorageFailure, runFeedbackCommand, readFeedbackAttachment } from '../../data/product-feedback/repository.ts'
import { currentClassification, dateShift, jakartaInstant } from '../../data/product-feedback/model.ts'
import { activeIssue, businessDay, commentStamp, currentPlan, eligibleEvidence, issueActions, issueBasis, issueDue, issueEvidenceValid, issueProgress, issueStatuses, latestFormalPlan, judgmentFor, phase2, planComments, reviewPreview, reviewStillCurrent, scopeContains, scopeForComments, translationFor } from '../../data/product-feedback/phase2-model.ts'
import { FEEDBACK_OWNER, FEEDBACK_THEMES, type FeedbackCommand, type FeedbackComment, type FeedbackSnapshot } from '../../data/product-feedback/types.ts'
import { FEEDBACK_ACTION_TYPES, type FeedbackIssue, type FeedbackIssueAction, type FeedbackIssuePlan, type FeedbackIssueReview, type FeedbackIssueScope, type FeedbackReviewPeriod } from '../../data/product-feedback/phase2-types.ts'
import { h, btn, action, field, select, inputClass, drawer, notice, replacePage, updateOverlay, bindLocalBehavior, registerLeaveGuard, prepareFeedbackList, renderFeedbackColumnDialog, listAction, pageSizeInput, renderFeedbackFilters, downloadCsv, styleName, skuName, storeName, productCell, rating, dateText, commentsUrl, pct, imageDialog, type ListState } from '../../components/product-feedback/insights-shared.ts'

const prefix='feedback-issues'
type FormKind='issue'|'state'|'evidence'|'action'|'plan'|'review'|'judgment'|'columns'|'image'|'saved-review'
interface Form {kind:FormKind; values:Record<string,string>; object:any; expectedVersion:number; dirty:boolean; error:string; files:Array<{id:string;blob:File}>; token:string; parent?:Form|null}
interface Query {status:string;owner:string;search:string;start:string;end:string;theme:string;priority:string;sku:string;store:string;listing:string;createdStart:string;createdEnd:string;todo:string;include:string}
const blankQuery=():Query=>({status:'',owner:'',search:'',start:'',end:'',theme:'',priority:'',sku:'',store:'',listing:'',createdStart:'',createdEnd:'',todo:'',include:''})
const state:ListState & {snapshot:FeedbackSnapshot|null;query:Query;draft:Query;dialog:Form|null;id:string;tab:string;error:string;message:string;busy:boolean;url:string;initialized:boolean}={page:1,sort:null,preferences:null,snapshot:null,query:blankQuery(),draft:blankQuery(),dialog:null,id:'',tab:'overview',error:'',message:'',busy:false,url:'',initialized:false}
let suspendedForm:{key:string;form:Form;id:string;tab:string;scroll:number;commentId:string}|null=null
const snap=()=>phase2(state.snapshot!)
const current=()=>snap().issues.find(i=>i.id===state.id&&!i.cancelledDraft)
const iid=(id:string)=>`/pcs/product-feedback/issues/${encodeURIComponent(id)}${location.pathname==='/pcs/product-feedback/issues'&&location.search?'?listQuery='+encodeURIComponent(location.search):''}`
const link=(url:string,text:string)=>`<a data-nav class="text-primary hover:underline" href="${h(url)}">${h(text)}</a>`
function area(name:string,label:string,value:string,rows=3):string{return `<label class="block text-xs text-muted-foreground">${h(label)}<textarea aria-label="${h(label)}" data-${prefix}-field="${name}" data-skip-page-rerender="true" class="mt-1 block w-full rounded border p-2 text-sm text-foreground" rows="${rows}">${h(value)}</textarea></label>`}
const tag=(label:string)=>`<span class="inline-flex rounded px-2 py-1 text-xs ${/已完成|已关闭/.test(label)?'bg-emerald-50 text-emerald-700':/待处理|待复盘/.test(label)?'bg-amber-50 text-amber-700':/处理中|进行中/.test(label)?'bg-blue-50 text-blue-700':label==='紧急'?'bg-red-50 text-red-700':'bg-muted'}">${h(label)}</span>`
function form(kind:FormKind,object:any={},values:Record<string,string>={}):void{state.dialog={kind,object,values,expectedVersion:current()?.version||0,dirty:false,error:'',files:[],token:''};overlay()}
function formInput(name:string,label:string,type='text'):string{return field(prefix,name,label,state.dialog!.values[name]||'',type)}
function ownerSelect(name:string,label:string,value:string):string{return select(prefix,name,label,value,[[FEEDBACK_OWNER,FEEDBACK_OWNER]])}
function issueRows(q=state.query,includeTodo=true):FeedbackIssue[]{return snap().issues.filter(i=>!i.cancelledDraft&&(!q.include?(!['草稿','已作废'].includes(i.status)||q.status===i.status):q.include==='草稿'?i.status==='草稿':q.include==='已作废'?i.status==='已作废':true)&&(!q.status||i.status===q.status)&&(!q.owner||i.owner===q.owner||issueActions(snap(),i).some(a=>a.owner===q.owner))&&(!q.search||[i.number,i.title,styleName(i.scope.styleId)].join(' ').toLowerCase().includes(q.search.toLowerCase()))&&(!q.start||i.targetDate>=q.start)&&(!q.end||i.targetDate<=q.end)&&(!q.theme||i.theme===q.theme)&&(!q.priority||i.priority===q.priority)&&(!q.sku||i.scope.skuIds.includes(q.sku))&&(!q.store||i.scope.storeIds.includes(q.store))&&(!q.listing||i.scope.listingIds.includes(q.listing))&&(!q.createdStart||businessDay(i.createdAt)>=q.createdStart)&&(!q.createdEnd||businessDay(i.createdAt)<=q.createdEnd)&&(!includeTodo||!q.todo||(q.todo==='overdue'?issueDue(snap(),i).overdueActions>0:q.todo==='review'?issueDue(snap(),i).reviewDue:q.todo==='evidence'?issueDue(snap(),i).changedEvidence>0:q.todo==='processing'?issueDue(snap(),i).processingOverdue:q.todo==='any'?i.status==='待处理'||issueDue(snap(),i).overdueActions>0||issueDue(snap(),i).reviewDue||issueDue(snap(),i).changedEvidence>0:true)))}
function columns():StandardListColumn<FeedbackIssue>[] {return [
 {key:'object',title:'单号／问题',width:270,required:true,freezeable:true,sortable:true,sortValue:i=>i.number,render:i=>`${link(iid(i.id),i.number||'未提交草稿')}<p class="mt-1 whitespace-normal font-medium">${h(i.title||'未填写标题')}</p>`},
 {key:'product',title:'商品／主主题',width:230,sortable:true,sortValue:i=>styleName(i.scope.styleId),render:i=>`<p>${h(styleName(i.scope.styleId))}</p><p class="mt-1 text-xs">${h(i.theme)}</p>`},
 {key:'scope',title:'处理范围',width:190,render:i=>`${i.scope.skuIds.length} 个SKU · ${i.scope.listingIds.length} 个链接<p class="text-xs">${i.scope.storeIds.map(storeName).map(h).join('、')}</p>${i.scope.includeUnknown?'<p class="text-xs">含SKU未确定项</p>':''}`},
 {key:'owner',title:'负责人',width:150,sortable:true,sortValue:i=>i.owner,render:i=>h(i.owner)},
 {key:'priority',title:'优先级',width:90,sortable:true,sortValue:i=>i.priority,render:i=>tag(i.priority)},
 {key:'status',title:'状态',width:110,sortable:true,sortValue:i=>i.status,render:i=>tag(i.status)},
 {key:'target',title:'本轮计划处理日',width:160,sortable:true,sortValue:i=>i.targetDate,render:i=>`<p class="${issueDue(snap(),i).processingOverdue?'text-red-700':''}">${h(i.targetDate||'待填写')}${issueDue(snap(),i).processingOverdue?' · 逾期':''}</p><p class="text-xs text-muted-foreground">第${i.round}轮</p>`},
 {key:'progress',title:'本轮行动',width:145,render:i=>{const p=issueProgress(snap(),i),d=issueDue(snap(),i);return `${p.total?`${p.done} / ${p.total} 已完成`:'本轮尚无行动'}${d.overdueActions?`<p class="text-xs text-red-700">逾期${d.overdueActions}项</p>`:''}${d.reviewDue?'<p class="text-xs text-amber-700">复盘已到期</p>':''}${d.changedEvidence?`<p class="text-xs text-amber-700">${d.changedEvidence}条证据待核对</p>`:''}`}},
 {key:'evidence',title:'当前有效证据',width:130,render:i=>String(i.evidence.filter(e=>issueEvidenceValid(snap(),i,e)).length)},
 {key:'updated',title:'最近更新',width:165,sortable:true,sortValue:i=>i.updatedAt,render:i=>h(dateText(i.updatedAt))},
 {key:'actions',title:'操作',width:100,actionColumn:true,render:i=>link(iid(i.id),i.status==='草稿'?'编辑草稿':'查看')},
]}
function queryHtml():string {const q=state.draft;return renderFeedbackFilters({actionPrefix:prefix,fieldsHtml:`${select(prefix,'status','状态',q.status,[['','全部状态'],...issueStatuses.map(v=>[v,v] as [string,string])])}${select(prefix,'owner','负责人',q.owner,[['','全部人员'],[FEEDBACK_OWNER,FEEDBACK_OWNER]])}${field(prefix,'search','SPU／单号／问题',q.search)}${field(prefix,'start','计划处理开始日',q.start,'date')}<details class="w-full"><summary class="cursor-pointer text-sm text-primary">更多条件</summary><div class="mt-3 grid grid-cols-3 gap-3">${field(prefix,'end','计划处理结束日',q.end,'date')}${select(prefix,'theme','主主题',q.theme,[['','全部主题'],...FEEDBACK_THEMES.map(v=>[v,v] as [string,string])])}${select(prefix,'priority','优先级',q.priority,[['','全部'],...['普通','优先','紧急'].map(v=>[v,v] as [string,string])])}${select(prefix,'sku','SKU',q.sku,[['','全部规格'],...[...new Set(snap().comments.flatMap(c=>c.association.skuId?[c.association.skuId]:[]))].map(id=>[id,skuName(id)] as [string,string])])}${select(prefix,'store','店铺',q.store,[['','全部店铺'],...[...new Set(snap().comments.map(c=>c.raw.storeId))].map(id=>[id,storeName(id)] as [string,string])])}${select(prefix,'listing','商品链接',q.listing,[['','全部链接'],...[...new Set(snap().comments.map(c=>c.association.listingId))].map(id=>[id,`${storeName(snap().comments.find(c=>c.association.listingId===id)!.raw.storeId)} · ${snap().comments.find(c=>c.association.listingId===id)!.raw.platformProductId}`] as [string,string])])}${field(prefix,'createdStart','创建开始日',q.createdStart,'date')}${field(prefix,'createdEnd','创建结束日',q.createdEnd,'date')}${select(prefix,'include','草稿／作废',q.include,[['','不含草稿和作废'],['全部','包含全部'],['草稿','仅草稿'],['已作废','仅作废']])}${select(prefix,'todo','待办',q.todo,[['','全部'],['any','全部待办'],['overdue','有逾期行动'],['review','到期复盘'],['evidence','证据待核对'],['processing','本轮处理逾期']])}</div></details>`,extraActionsHtml:btn(prefix,'export','导出跟进')})}
function issueStats(items:Array<{label:string;value:number;attrs:string}>):string {return `<div data-standard-list-stats>${items.map(item=>`<button class="flex min-h-20 flex-col items-start justify-center gap-1 rounded-lg border bg-card p-3 text-left hover:bg-muted" ${item.attrs}><span class="text-xs text-muted-foreground">${h(item.label)}</span><strong class="text-lg">${item.value}</strong></button>`).join('')}</div>`}
function listBody():string{const rows=issueRows(),base=issueRows({...state.query,status:'',todo:''},false),parts=prepareFeedbackList(state,prefix,columns(),rows),overdue=base.reduce((n,i)=>n+issueDue(snap(),i).overdueActions,0);return renderStandardListPage({className:'product-feedback-page',title:'问题跟进',primaryActionsHtml:`<div class="feedback-actions">${btn(prefix,'new','新建跟进','',true)}${btn(prefix,'refresh','刷新')}</div>`,statusTabsHtml:`<div class="feedback-actions">${btn(prefix,'all','全部跟进')}${btn(prefix,'person','人员待办')}</div>`,filtersHtml:queryHtml(),feedbackHtml:notice(state.error,state.message),statsHtml:issueStats([{label:'待处理（条）',value:base.filter(i=>i.status==='待处理').length,attrs:action(prefix,'stat')+' data-status="待处理"'},{label:'处理中（条）',value:base.filter(i=>i.status==='处理中').length,attrs:action(prefix,'stat')+' data-status="处理中"'},{label:'逾期行动（项）',value:overdue,attrs:action(prefix,'stat')+' data-todo="overdue"'},{label:'到期复盘（项）',value:base.filter(i=>issueDue(snap(),i).reviewDue).length,attrs:action(prefix,'stat')+' data-todo="review"'},{label:'证据变化（条跟进）',value:base.filter(i=>issueDue(snap(),i).changedEvidence).length,attrs:action(prefix,'stat')+' data-todo="evidence"'}]),listTitle:`跟进列表 · ${rows.length}条${state.query.todo==='overdue'?` · ${rows.reduce((n,i)=>n+issueDue(snap(),i).overdueActions,0)}项逾期行动`:''}`,listActionsHtml:btn(prefix,'columns','列设置'),tableHtml:renderStandardListTable(parts.tableOptions),paginationHtml:renderTablePagination(parts.paginationOptions),overlaysHtml:`<div id="${prefix}-overlay">${dialogHtml()}</div>`})}
function commentCard(c:FeedbackComment,extra=''):string{const t=translationFor(snap(),c);return `<article class="rounded border p-3 text-sm"><div class="flex flex-wrap items-center justify-between gap-2"><span>${h(c.raw.author)} · ${rating(c.raw.rating)}</span>${state.dialog?.kind==='issue'?btn(prefix,'classify-comment','查看／标注',`data-id="${h(c.id)}"`):link(commentsUrl({start:'',end:''},{commentId:c.id,returnTo:location.pathname+location.search}),'查看／标注')}</div><p class="mt-2 whitespace-pre-wrap">${h(c.raw.content||'仅评分，无正文')}</p>${t?`<p class="mt-2 text-muted-foreground">中文：${h(t.text)}</p>`:''}<p class="mt-2 text-xs text-muted-foreground">${h(storeName(c.raw.storeId))} · ${h(skuName(c.association.skuId))} · ${h(dateText(c.raw.commentAt))}</p>${extra}</article>`}
function actionCard(a:FeedbackIssueAction,i:FeedbackIssue):string{const editable=activeIssue(i)&&a.round===i.round;return `<article class="rounded border p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-medium">${h(a.content)}</h3>${tag(a.status)}</div><p class="mt-2 text-sm">${h(a.owner)} · 计划${h(a.dueDate)} · 第${a.round}轮</p>${a.result?`<p class="mt-2 text-sm">实际结果：${h(a.result)}</p><p class="mt-1 text-sm">${h(a.effect)}${a.effectiveAt?` · 生效${h(dateText(a.effectiveAt))}`:''}</p><p class="text-xs text-muted-foreground">${h(a.effectEvidence)}</p>`:''}${a.progress.length?`<details class="mt-2"><summary class="text-sm text-primary">进展与修改记录</summary>${a.progress.map(p=>`<p class="mt-2 whitespace-pre-wrap text-xs">${h(p)}</p>`).join('')}</details>`:''}${a.attachmentIds.map(id=>{const f=snap().actionAttachments.find(f=>f.id===id);return f?btn(prefix,'attachment',f.name,`data-id="${h(id)}"`):''}).join('')}<div class="mt-3 flex flex-wrap gap-2">${editable?`${['未开始','进行中'].includes(a.status)?btn(prefix,'edit-action','编辑',`data-id="${h(a.id)}"`):''}${(a.status==='未开始'?['开始','完成','取消']:a.status==='进行中'?['进展','完成','取消']:a.status==='已完成'?['修正','恢复']:['恢复']).map(intent=>btn(prefix,'action-form',intent==='恢复'?'恢复处理':intent,`data-id="${h(a.id)}" data-intent="${intent}"`)).join('')}`:''}</div></article>`}
function reviewPeriodHtml(title:string,p:FeedbackReviewPeriod|null):string{if(!p)return '';return `<section class="rounded border p-3"><h4 class="font-semibold">${h(title)}</h4><dl class="mt-2 grid grid-cols-2 gap-2 text-sm"><dt>评论／有效评分</dt><dd>${p.total} / ${p.rated}</dd><dt>均分</dt><dd>${p.average?.toFixed(2)||'—'}</dd><dt>差评数／率</dt><dd>${p.negative} / ${pct(p.rated?p.negative/p.rated:null)}</dd><dt>全部主题问题</dt><dd>${p.problem} / ${p.total}</dd><dt>本次问题已识别</dt><dd>${p.Y} / ${p.total} · ${pct(p.total?p.Y/p.total:null)}</dd><dt>支持／不支持</dt><dd>${p.Y} / ${p.N}</dd><dt>信息不足／待核对</dt><dd>${p.U} / ${p.R}</dd><dt>核对完成率</dt><dd>${pct(p.total?(p.Y+p.N+p.U)/p.total:null)}</dd></dl>${p.rated<20?'<p class="mt-2 text-xs text-amber-700">小样本</p>':''}${p.coverage.length?`<details class="mt-2 text-sm text-amber-700"><summary>采集范围未齐 · 查看缺口</summary>${p.coverage.map(g=>`<p class="break-all">${h(g)}</p>`).join('')}${link('/pcs/product-feedback/batches','查看采集记录')}</details>`:''}</section>`}
function detailBody(i:FeedbackIssue):string{const p=issueProgress(snap(),i),due=issueDue(snap(),i),editable=activeIssue(i),plan=currentPlan(snap(),i),tabs=[['overview','概览'],['evidence','评论证据'],['actions','处理行动'],['review','复盘'],['history','操作历史']];let body='';if(state.tab==='overview')body=`<div class="grid gap-4 lg:grid-cols-2"><section class="rounded border p-4"><h3 class="font-semibold">问题描述</h3><p class="mt-2 whitespace-pre-wrap">${h(i.description)}</p><h4 class="mt-4 font-medium">本次问题判定说明</h4><p class="mt-2">${h(i.definition)}</p><h4 class="mt-4 font-medium">固定处理范围</h4><p class="mt-2 text-sm">${h(i.scope.mode)} · ${i.scope.includeUnknown?'包含SKU未确定项':'仅明确SKU'}</p><p class="mt-2 break-words text-xs">${i.scope.skuIds.map(skuName).map(h).join('、')}</p><p class="mt-2 text-sm">${i.scope.storeIds.map(storeName).map(h).join('、')}</p><p class="mt-2 text-xs">${i.scope.listingIds.map(id=>h(snap().comments.find(c=>c.association.listingId===id)?.raw.platformProductId||id)).join('、')}</p></section><section class="rounded border p-4"><h3 class="font-semibold">本轮处理</h3><p class="mt-2">${p.total?`${p.done}/${p.total}项行动已完成`:'本轮尚无行动'}</p><p class="mt-2">当前有效证据${i.evidence.filter(e=>issueEvidenceValid(snap(),i,e)).length}条</p><p class="mt-2">${plan?`计划复盘日 ${plan.dueDate}`:'尚无当前复盘计划'}</p>${i.status==='已关闭'?`<p class="mt-3">关闭时间 ${h(dateText(i.closedAt))}</p><p>${h(i.closeReason)}</p>`:''}<div class="mt-4">${link(`/pcs/product-feedback/products?dimension=spu&objectId=${encodeURIComponent(i.scope.styleId)}&styleId=${encodeURIComponent(i.scope.styleId)}&start=&end=`,'查看商品诊断')}</div></section></div>`
 else if(state.tab==='evidence')body=`<div class="mb-3 flex justify-end">${editable?btn(prefix,'evidence-form','添加证据'):''}</div><div class="space-y-3">${i.evidence.map(e=>{const c=snap().comments.find(c=>c.id===e.commentId);return c?commentCard(c,`<p class="mt-2 text-sm ${e.released?'text-muted-foreground':issueEvidenceValid(snap(),i,e)?'text-emerald-700':'text-amber-700'}">${e.released?'已解除引用':issueEvidenceValid(snap(),i,e)?'当前支持':'待重新核对'} · ${h(e.reason)}</p>${!e.released&&editable?`<div class="mt-2 flex gap-2">${btn(prefix,'evidence-check','重新核对',`data-id="${h(c.id)}"`)}${btn(prefix,'evidence-release','解除引用',`data-id="${h(c.id)}"`)}</div>`:''}<details class="mt-2 text-xs"><summary>保存时引用与历史</summary><p class="mt-2 whitespace-pre-wrap">${h(e.raw)}</p><p class="mt-2">核对依据：${e.translationId?'中文译文 · '+h(snap().translations.find(t=>t.id===e.translationId)?.text||'保存时译文未取得'):'原文与已确认分类'}</p>${e.history.map(x=>`<p class="mt-2">${h(x.raw)} · ${h(x.reason)} · ${h(dateText(x.at))}${x.translationId?' · 引用译文：'+h(snap().translations.find(t=>t.id===x.translationId)?.text||'未取得'):''}</p>`).join('')}</details>`):''}).join('')||'<p class="p-4 text-sm text-muted-foreground">尚无评论证据</p>'}</div>`
 else if(state.tab==='actions')body=`<div class="mb-3 flex flex-wrap justify-end gap-2">${editable?btn(prefix,'new-action','新增行动','',true):''}${btn(prefix,'export-actions','导出行动')}</div><div class="space-y-3">${snap().issueActions.filter(a=>a.issueId===i.id).map(a=>actionCard(a,i)).join('')||'<p class="p-4 text-sm">本轮尚无行动</p>'}</div>`
 else if(state.tab==='review')body=`<div class="mb-3 flex flex-wrap justify-end gap-2">${editable?btn(prefix,'new-plan',snap().issuePlans.some(p=>p.issueId===i.id&&p.round===i.round&&p.state==='草稿')?'继续编辑计划草稿':'制定复盘计划') : ''}</div>${plan?`<section class="rounded border p-4"><h3 class="font-semibold">当前计划 · ${h(plan.kind)}</h3><p class="mt-2">${h(plan.target)} · 计划${h(plan.dueDate)}</p>${plan.kind==='反馈变化'?`<p class="mt-2 text-sm">前期 ${businessDay(plan.before.start)}～${businessDay(new Date(Date.parse(plan.before.end)-1).toISOString())}<br>后期 ${businessDay(plan.after.start)}～${businessDay(new Date(Date.parse(plan.after.end)-1).toISOString())}</p>`:''}<div class="mt-3 flex gap-2">${editable?btn(prefix,'record-review','记录复盘',`data-id="${h(plan.id)}"`) : ''}</div></section>`:'<p class="rounded border p-4 text-sm">尚无当前正式计划</p>'}<h3 class="mt-5 font-semibold">复盘记录</h3><div class="mt-3 space-y-3">${snap().issueReviews.filter(r=>r.issueId===i.id).slice().reverse().map(r=>`<article class="rounded border p-3"><p class="font-medium">第${r.round}轮 · ${r.draft?'草稿':r.kind==='核查结论'?'核查结论':r.conclusion} · ${h(dateText(r.at))}</p><p class="mt-2 text-sm">${h(r.observation)}</p><p class="mt-1 text-xs">${h(r.decision)}${!r.draft&&!reviewStillCurrent(snap(),i,r)?' · 依据已有变化':''}</p><div class="mt-2 flex gap-2">${btn(prefix,'saved-review','查看保存时结果',`data-id="${h(r.id)}"`)}${editable?btn(prefix,'recalculate','重新观察',`data-id="${h(r.id)}"`):''}</div></article>`).join('')||'<p class="text-sm text-muted-foreground">尚无复盘记录</p>'}</div><details class="mt-4"><summary class="text-sm text-primary">计划历史</summary>${snap().issuePlans.filter(p=>p.issueId===i.id).map(p=>`<p class="mt-2 rounded border p-2 text-xs">第${p.round}轮 · ${h(p.state)} · ${h(p.dueDate)} · ${h(p.target)}</p>`).join('')}</details>`
 else body=`<div class="space-y-3">${snap().logs.filter(l=>l.objectId===i.id).slice().reverse().map(l=>`<article class="rounded border p-3 text-sm"><p>${h(l.detail)}</p><p class="mt-2 text-xs text-muted-foreground">${h(l.actor)} · ${h(dateText(l.at))}</p></article>`).join('')}</div>`
 return `<div class="product-feedback-page space-y-4"><div>${new URLSearchParams(location.search).get('returnTo')?.startsWith('/pcs/product-feedback/')?link(new URLSearchParams(location.search).get('returnTo')!,'← 返回来源')+' · ':''}${link('/pcs/product-feedback/issues'+(new URLSearchParams(location.search).get('listQuery')||''),'← 返回问题跟进')}</div><header class="flex flex-wrap items-start justify-between gap-3"><div><h1 class="text-xl font-semibold">${h(i.number||'跟进草稿')} · ${h(i.title||'未填写标题')}</h1><p class="mt-2 text-sm text-muted-foreground">${h(styleName(i.scope.styleId))} · ${h(i.theme)} · ${h(i.owner)} · 计划处理${h(i.targetDate)}</p></div><div class="feedback-actions">${tag(i.status)}${i.status==='草稿'?`${btn(prefix,'edit','编辑草稿','',true)}${btn(prefix,'state','取消草稿','data-intent="取消草稿"')}`:editable?`${btn(prefix,'edit','编辑')}${(i.status==='待处理'?['开始处理']:i.status==='处理中'?['进入复盘']:['继续处理','关闭']).map(x=>btn(prefix,'state',x==='关闭'?'关闭本次跟进':x,`data-intent="${x}"`)).join('')}${btn(prefix,'state','作废','data-intent="作废"')}`:i.status==='已关闭'?btn(prefix,'state','重开','data-intent="重开"'):''}${btn(prefix,'refresh','刷新')}</div></header>${notice(state.error,state.message)}${due.changedEvidence?`<p class="text-sm text-amber-700">${due.changedEvidence}条引用需重新核对</p>`:''}${due.processingOverdue?'<p class="text-sm text-red-700">本轮处理已逾期</p>':''}<nav class="flex flex-wrap gap-2">${tabs.map(([key,label])=>btn(prefix,'tab',label,`data-tab="${key}"`,state.tab===key)).join('')}</nav>${body}<div id="${prefix}-overlay">${dialogHtml()}</div></div>`}
function scopeChecks(scope:FeedbackIssueScope):string {const all=snap().comments.filter(c=>c.association.styleId===scope.styleId),skus=[...new Set([...listSkuArchivesByStyleId(scope.styleId).map(s=>s.skuId),...all.flatMap(c=>c.association.skuId?[c.association.skuId]:[])])],stores=[...new Set(all.map(c=>c.raw.storeId))],links=[...new Set(all.map(c=>c.association.listingId))];return `<div class="grid gap-3"><div>${select(prefix,'mode','范围模式',scope.mode,[['SPU固定范围','SPU固定范围'],['指定SKU','指定SKU']])}</div>${[['skuIds','规格',skus,skuName],['storeIds','店铺',stores,storeName],['listingIds','商品链接',links,(id:string)=>snap().comments.find(c=>c.association.listingId===id)?.raw.platformProductId||id]].map(([key,label,ids,name]:any)=>`<fieldset class="rounded border p-3"><legend class="px-1 text-sm">${h(label)}</legend><div class="grid gap-2 sm:grid-cols-2">${ids.map((id:string)=>`<label class="flex min-w-0 items-start gap-2 text-xs"><input type="checkbox" ${action(prefix,'scope-toggle')} data-key="${key}" data-id="${h(id)}" ${(scope as any)[key].includes(id)?'checked':''}><span class="break-all">${h(name(id))}</span></label>`).join('')}</div></fieldset>`).join('')}<label class="flex gap-2 text-sm"><input type="checkbox" ${action(prefix,'unknown-toggle')} ${scope.includeUnknown?'checked':''} ${scope.mode==='指定SKU'?'disabled':''}>包含SKU未确定项</label></div>`}
function issueForm(d:Form):string {const i=d.object as FeedbackIssue,styles=[...new Set(snap().comments.map(c=>c.association.styleId))],candidates=snap().comments.filter(c=>i.version&&i.status!=='草稿'?i.evidence.some(e=>e.commentId===c.id&&!e.released):scopeContains(i.scope,c)),similar=snap().issues.filter(x=>x.id!==i.id&&activeIssue(x)&&x.scope.styleId===i.scope.styleId&&x.theme===i.theme);return drawer(prefix,i.version?'编辑跟进':'新建跟进',`${notice(d.error,'')}<div class="grid grid-cols-2 gap-3">${formInput('title','问题标题')}${select(prefix,'styleId','款式',i.scope.styleId,styles.map(id=>[id,styleName(id)]))}${select(prefix,'theme','主要主题',i.theme,FEEDBACK_THEMES.map(t=>[t,t]))}${ownerSelect('owner','负责人',d.values.owner)}${select(prefix,'priority','优先级',d.values.priority,[['普通','普通'],['优先','优先'],['紧急','紧急']])}${formInput('targetDate','本轮计划处理日','date')}${formInput('discoveryStart','发现开始日','date')}${formInput('discoveryEnd','发现结束日','date')}</div><div class="mt-4 space-y-3">${area('description','问题描述',d.values.description)}${area('definition','本次问题判定说明',d.values.definition)}<h3 class="font-semibold">固定处理范围</h3>${scopeChecks(i.scope)}<h3 class="font-semibold">评论证据</h3>${i.version&&i.status!=='草稿'?'<p class="text-xs text-muted-foreground">引用调整请在详情的“评论证据”中操作</p>':''}${candidates.map(c=>`<div class="flex gap-2"><input type="checkbox" class="mt-4" aria-label="引用${h(c.raw.author)}" ${action(prefix,'evidence-toggle')} data-id="${h(c.id)}" ${i.evidence.some(e=>e.commentId===c.id&&!e.released)?'checked':''} ${i.version&&i.status!=='草稿'?'disabled':''}><div class="min-w-0 flex-1">${commentCard(c,`<p class="mt-2 text-xs ${eligibleEvidence(i,c)?'text-emerald-700':'text-amber-700'}">${eligibleEvidence(i,c)?'符合正式建单证据条件':'尚不符合正式建单证据条件'}</p>`)}</div></div>`).join('')}${similar.length?`<section class="rounded border p-3 text-sm"><h3 class="font-medium">已有相关跟进</h3>${similar.map(x=>`<p class="mt-2">${link(iid(x.id),`${x.number} ${x.title}`)}</p>`).join('')}${formInput('distinction','确需另建时说明区别')}</section>`:''}${i.version?formInput('reason','修改原因'):''}</div>`,`${!i.version||i.status==='草稿'?btn(prefix,'save-issue-draft','保存草稿'):''}${btn(prefix,'save-issue',i.version&&i.status!=='草稿'?'保存修改':'创建跟进','',true)}`,'760px')}
function actionForm(d:Form):string {const a=d.object as FeedbackIssueAction,intent=d.values.intent;return drawer(prefix,intent==='保存'?'行动内容':`${intent==='恢复'?'恢复处理':intent}行动`,`${notice(d.error,'')}<div class="space-y-3">${intent==='保存'?`${select(prefix,'type','行动类型',d.values.type,FEEDBACK_ACTION_TYPES.map(t=>[t,t]))}${area('content','行动内容',d.values.content)}${ownerSelect('owner','行动负责人',d.values.owner)}${formInput('dueDate','计划完成日','date')}`:`<p class="font-medium">${h(a.content)}</p>`}${['完成','修正'].includes(intent)?`${formInput('completedAt','实际完成时间（雅加达）','datetime-local')}${area('result','实际结果',d.values.result)}${select(prefix,'effect','生效情况',d.values.effect,[['','请选择'],['无需观察','无需观察'],['已生效','已生效'],['生效时间未确认','生效时间未确认']])}${d.values.effect==='已生效'?formInput('effectiveAt','实际生效时间（雅加达）','datetime-local'):''}${area('effectEvidence',d.values.effect==='无需观察'?'核查结论':'生效依据／待核查事项',d.values.effectEvidence)}`:''}${['保存','修正'].includes(intent)?a.attachmentIds.map(id=>`<p class="text-xs">${h(snap().actionAttachments.find(f=>f.id===id)?.name||'附件')}${btn(prefix,'remove-existing-file','移除引用',`data-id="${h(id)}"`)}</p>`).join(''):''}${['保存','完成','修正'].includes(intent)?`<label class="block text-sm">附加证据（最多5个，单个10MB）<input type="file" multiple accept="image/png,image/jpeg,image/webp,application/pdf" data-${prefix}-files data-skip-page-rerender="true" class="mt-2 block w-full"></label>${d.files.map(f=>`<p class="text-xs">${h(f.blob.name)} ${btn(prefix,'remove-file','移除',`data-id="${f.id}"`)}</p>`).join('')}`:''}${intent!=='保存'||a.version?area('reason',intent==='进展'?'本次进展':'操作原因',d.values.reason):''}${intent==='恢复'||current()?.status==='待复盘'?formInput('targetDate','本轮计划处理日','date'):''}</div>`,btn(prefix,'save-action',intent==='保存'?'保存行动':`确认${intent==='恢复'?'恢复处理':intent}`,'',true),'720px')}
function planForm(d:Form):string{const p=d.object as FeedbackIssuePlan,i=current()!,actions=issueActions(snap(),i).filter(a=>a.status==='已完成'),kind=d.values.kind;return drawer(prefix,'制定复盘计划',`${notice(d.error,'')}<div class="space-y-3">${select(prefix,'kind','复盘类型',kind,[['反馈变化','反馈变化复盘'],['核查结论','核查结论复盘']])}<fieldset class="rounded border p-3"><legend class="text-sm">本次依据行动</legend>${actions.map(a=>`<label class="mt-2 flex gap-2 text-sm"><input type="checkbox" ${action(prefix,'plan-action-toggle')} data-id="${h(a.id)}" ${p.actionIds.includes(a.id)?'checked':''}>${h(a.content)} · ${h(a.effect)}</label>`).join('')||'<p class="text-sm">请先完成本轮有效行动</p>'}</fieldset>${kind==='反馈变化'?`${select(prefix,'anchorActionId','实际生效锚点',d.values.anchorActionId,[['','请选择已生效行动'],...actions.filter(a=>a.effect==='已生效').map(a=>[a.id,`${a.content} · ${dateText(a.effectiveAt)}`] as [string,string])])}<div class="grid grid-cols-2 gap-3">${formInput('days','前后各观察天数','number')}${formInput('lag','生效后滞后天数','number')}</div>`:''}${formInput('dueDate','计划复盘日','date')}${area('target',kind==='核查结论'?'本次核查目标':'本次观察目标',d.values.target)}<details><summary class="text-sm text-primary">观察范围</summary>${scopeChecks(p.scope)}</details>${formInput('reason','计划说明／替换原因')}</div>`,`${btn(prefix,'save-plan-draft','保存草稿')}${btn(prefix,'save-plan','保存正式计划','',true)}`,'760px')}
function reviewForm(d:Form):string{const i=current()!,p=d.object.plan as FeedbackIssuePlan,preview=reviewPreview(snap(),i,p);return drawer(prefix,'记录复盘',`${notice(d.error,'')}<p class="mb-3 text-sm">${h(p.target)} · ${h(p.kind)} · 第${p.round}轮</p>${p.kind==='反馈变化'?`<div class="grid grid-cols-2 gap-3">${reviewPeriodHtml(`前期 ${businessDay(p.before.start)}～${businessDay(new Date(Date.parse(p.before.end)-1).toISOString())}`,preview.before)}${reviewPeriodHtml(`后期 ${businessDay(p.after.start)}～${businessDay(new Date(Date.parse(p.after.end)-1).toISOString())}`,preview.after)}</div>${!preview.ended?'<p class="mt-3 text-sm text-amber-700">后期尚未完整结束，仅可保存草稿</p>':''}${!preview.sufficient?'<p class="mt-3 text-sm text-amber-700">数据条件不足，暂不能判断反馈变化</p>':''}<details class="mt-3"><summary class="text-sm text-primary">核对具体问题评论</summary><div class="mt-3 space-y-3">${preview.samples.map(x=>{const c=snap().comments.find(c=>c.id===x.id)!;const j=judgmentFor(snap(),i,p,c);return commentCard(c,`<div class="mt-2 flex items-center gap-2">${tag(j?{Y:'支持',N:'不支持',U:'信息不足'}[j.result]:'待核对')}${btn(prefix,'judge','核对',`data-id="${h(c.id)}" data-plan="${h(p.id)}"`)}</div>`)}).join('')}</div></details>`:`<section class="rounded border p-3"><h3 class="font-medium">本轮核查依据</h3>${issueActions(snap(),i).filter(a=>a.status!=='已取消').map(a=>`<p class="mt-2 text-sm">${h(a.content)}：${h(a.result)}<br>${h(a.effectEvidence)}</p>`).join('')}</section>`}<div class="mt-4 space-y-3">${area('observation',p.kind==='核查结论'?'核查结论':'观察记录',d.values.observation)}${area('factors','影响因素／局限',d.values.factors)}${select(prefix,'decision','后续决定',d.values.decision,[['继续观察','继续观察'],['调整措施','调整措施'],['结束本次跟进','结束本次跟进']])}${d.values.decision==='结束本次跟进'?`${area('endingReason','结束原因',d.values.endingReason)}${area('nextStep','后续安排',d.values.nextStep)}`:d.values.decision==='继续观察'?`${area('nextStep','下次观察目标',d.values.nextStep)}${formInput('nextDueDate','下次复盘日','date')}`:formInput('targetDate','本轮计划处理日','date')}</div>`,`${btn(prefix,'preview-review','重新预览')}${btn(prefix,'save-review-draft','保存草稿')}${btn(prefix,'save-review','保存正式复盘','',true)}`,'1000px')}
function dialogHtml():string {const d=state.dialog;if(!d)return '';if(d.kind==='columns')return renderFeedbackColumnDialog(state,prefix,columns());if(d.kind==='image')return imageDialog(prefix,d.values.url,d.values.label);if(d.kind==='issue')return issueForm(d);if(d.kind==='action')return actionForm(d);if(d.kind==='plan')return planForm(d);if(d.kind==='review')return reviewForm(d);if(d.kind==='saved-review'){const r=d.object as FeedbackIssueReview;return drawer(prefix,'保存时复盘结果',`<p class="font-semibold">${h(r.draft?'复盘草稿':r.conclusion)} · ${h(dateText(r.at))}</p><div class="mt-3 grid grid-cols-2 gap-3">${reviewPeriodHtml('前期',r.before)}${reviewPeriodHtml('后期',r.after)}</div><p class="mt-3 whitespace-pre-wrap">${h(r.observation)}</p><p class="mt-3 text-sm">影响因素：${h(r.factors)}</p><p class="mt-3">${h(r.decision)} · ${h(r.endingReason)}</p><p class="mt-3">${h(r.nextStep)}</p><details class="mt-3"><summary>保存时评论证据</summary>${r.samples.map(c=>`<p class="mt-2 rounded border p-2 text-sm">${h(c.raw||'仅评分')} · ${c.rating??'未评分'}星</p>`).join('')}</details>`,btn(prefix,'export-review','导出保存时结果',`data-id="${h(r.id)}"`),'1000px')}
 if(d.kind==='state')return drawer(prefix,d.values.intent==='关闭'?'关闭本次跟进':d.values.intent,`${notice(d.error,'')}<p class="mb-3 font-medium">${h(current()?.number||'跟进草稿')} · ${h(current()?.title)}</p><div class="space-y-3">${area('reason',d.values.intent==='关闭'?'关闭原因':'操作原因',d.values.reason)}${['继续处理','重开'].includes(d.values.intent)?`${formInput('targetDate','本轮计划处理日','date')}`:''}${d.values.intent==='重开'?`${ownerSelect('owner','本轮负责人',d.values.owner)}${area('goal','本轮处理目标',d.values.goal)}`:''}</div>`,btn(prefix,'save-state',`确认${d.values.intent==='关闭'?'关闭本次跟进':d.values.intent}`,'',true),'680px')
 if(d.kind==='evidence'){const i=current()!,rows=d.values.intent==='添加'?snap().comments.filter(c=>scopeContains(i.scope,c)):snap().comments.filter(c=>c.id===d.values.commentId);return drawer(prefix,d.values.intent==='添加'?'添加评论证据':'核对评论证据',`${notice(d.error,'')}<div class="space-y-3">${rows.map(c=>`<div class="flex gap-2"><input aria-label="选择${h(c.raw.author)}的评论" class="mt-4" type="checkbox" ${action(prefix,'pick-comment')} data-id="${h(c.id)}" ${d.values.ids.split(',').includes(c.id)?'checked':''}><span class="min-w-0 flex-1">${commentCard(c)}${d.values.intent!=='解除'?select(prefix,'evidenceBasis:'+c.id,'核对依据',d.values['evidenceBasis:'+c.id]||(i.evidence.find(e=>e.commentId===c.id)?.translationId&&translationFor(snap(),c)?'中文译文':'原文'),[['原文','原文与已确认分类'],...(translationFor(snap(),c)?[['中文译文','当前中文译文'] as [string,string]]:[])]):''}</span></div>`).join('')}${area('reason','引用／核对说明',d.values.reason)}</div>`,btn(prefix,'save-evidence',d.values.intent==='解除'?'确认解除引用':d.values.intent==='仍支持'?'核对仍支持':'添加证据','',true),'760px')}
 const c=snap().comments.find(c=>c.id===d.values.commentId)!,translation=translationFor(snap(),c);return drawer(prefix,'核对本次具体问题',`${notice(d.error,'')}<p class="mb-3 rounded bg-muted p-3 text-sm">${h(current()!.definition)}</p>${commentCard(c)}<div class="mt-3 space-y-3">${select(prefix,'result','核对结果',d.values.result,[['Y','支持本次问题'],['N','不支持'],['U','信息不足']])}${select(prefix,'basis','判断依据',d.values.basis,[['原文','原文'],...(c.raw.images.length?[['图片','来源图片'] as [string,string]]:[]),...(translation?[['中文译文','当前中文译文'] as [string,string]]:[])])}${area('evidence','原句片段／判断说明',d.values.evidence)}</div>`,btn(prefix,'save-judgment','保存核对','',true),'760px')
}
function renderBody():string {
 const i=current()
 if(state.id){
  if(i)return `<div id="${prefix}-root" data-skip-page-rerender="true" class="min-w-0 max-w-full">${detailBody(i)}</div>`
  return `<div id="${prefix}-root" data-skip-page-rerender="true" class="min-w-0 max-w-full"><div class="p-6">${notice(state.error||'记录不存在或当前资料不可读','')}${link('/pcs/product-feedback/issues','返回问题跟进')}</div></div>`
 }
 return `<div id="${prefix}-root" data-skip-page-rerender="true" class="min-w-0 max-w-full">${listBody()}</div>`
}
function overlay():void{updateOverlay(prefix,dialogHtml())}
function renderLocal():void{replacePage(prefix,renderBody());bindLocalBehavior(prefix,renderLocal,state)}
async function reload():Promise<void>{await ensureFeedbackState();if(getFeedbackStorageFailure())throw new Error(getFeedbackStorageFailure());state.snapshot=getFeedbackSnapshot()}
function dirty():boolean{return !!state.dialog?.dirty}
export function confirmFeedbackIssuesLeave():boolean{if(dirty()&&!window.confirm('有未保存的输入，放弃修改并离开？'))return false;state.dialog=null;return true}
export function getFeedbackIssuesDialog():Form|null{return state.dialog}
function sourceIssue(cids:string[],styleId:string):FeedbackIssue {const today=businessDay(snap().asOf),scope=scopeForComments(snap().comments,styleId);return{id:crypto.randomUUID(),number:'',title:'',description:'',definition:'',theme:'面料与穿着',scope,discovery:{start:dateShift(today,-29),end:today},owner:FEEDBACK_OWNER,priority:'普通',targetDate:dateShift(today,3),status:'草稿',round:1,version:0,definitionVersion:1,evidence:cids.map(id=>({commentId:id,reason:''} as any)),createdAt:'',updatedAt:'',actor:FEEDBACK_OWNER,closedAt:'',closeReason:'',relatedIssueId:''}}
function openIssue(i:FeedbackIssue):void {form('issue',structuredClone(i),{title:i.title,description:i.description,definition:i.definition,owner:i.owner,priority:i.priority,targetDate:i.targetDate,discoveryStart:i.discovery.start,discoveryEnd:i.discovery.end,theme:i.theme,reason:'',distinction:''});state.dialog!.expectedVersion=i.version}
function blankAction(i:FeedbackIssue):FeedbackIssueAction{return{id:crypto.randomUUID(),issueId:i.id,round:i.round,version:0,type:'商品核查',content:'',owner:FEEDBACK_OWNER,dueDate:i.targetDate,status:'未开始',startedAt:'',completedAt:'',result:'',effect:'',effectiveAt:'',effectEvidence:'',progress:[],attachmentIds:[]}}
